  $polcjson${"slug": "policing-in-america", "title": "Policing in America", "description": "Policing in America situates law enforcement as an evolving public authority shaped by local government, race, labor, immigration, social control, reform movements, and public safety demands. Students study history and mission, organization and governance, recruitment and culture, patrol and calls for service, discretion, constitutional limits on stops, searches, arrests, and interrogation, investigations and intelligence, use of force, community and problem-oriented policing, race and legitimacy, accountability, crime data and evidence-based practice, technology and surveillance, specialized contexts and vulnerable populations, officer wellness and ethics, homeland security and federalism, and reform policy design.", "topics": [{"id": "b88b67dc-ff08-4da1-89da-69dad78d4131", "type": "topic", "title": "Foundations and History of Policing in America", "description": "This opening unit situates American policing historically and institutionally. Students learn that policing is not a single agency function but an evolving public authority shaped by local government, race, labor, immigration, social control, reform movements, and public safety demands.", "children": [{"id": "b408d5ae-9e81-43ca-b756-c362432e487e", "type": "subtopic", "title": "Historical development", "children": [{"id": "c4c8fcda-c688-44a2-8b67-ecfca9eafaf9", "type": "concept", "title": "Colonial watch systems"}, {"id": "935870b0-4330-426d-a6c3-c33483544791", "type": "concept", "title": "Slave patrols"}, {"id": "a75657f0-d5e9-4b25-bab8-85f04122db01", "type": "concept", "title": "Municipal police"}, {"id": "7c2b5c77-a5da-455d-a246-b9e44b0b4253", "type": "concept", "title": "Political era"}, {"id": "dddfb846-30c6-4e54-bec3-b73df4384e76", "type": "concept", "title": "Professional era"}, {"id": "0881ec35-880e-4836-88c2-00d070e30af9", "type": "concept", "title": "Reform era"}, {"id": "bf46cea6-8d1b-423b-a80c-d8527426f355", "type": "concept", "title": "Community policing era"}, {"id": "05093e73-1395-4c95-91ac-938c98fb95f1", "type": "concept", "title": "Homeland security era"}], "description": "Students learn how American policing emerged through competing models of order maintenance, professionalization, and community control."}, {"id": "0ccb4f6e-bf24-4099-96cc-aff0c4258829", "type": "subtopic", "title": "Legitimacy and mission", "children": [{"id": "82af5cb4-79d7-4fd3-bed6-b4d3a57c30fa", "type": "concept", "title": "Public order"}, {"id": "243f5cb2-c991-4fe7-8627-bca45e52b725", "type": "concept", "title": "Crime control"}, {"id": "d1c634e6-e719-4249-81f0-231c97a8936e", "type": "concept", "title": "Service role"}, {"id": "b0f096e4-c85e-4e11-b328-5469523232f3", "type": "concept", "title": "Social control"}, {"id": "cbb0c165-3578-4016-b259-9f0950dd21dc", "type": "concept", "title": "Procedural justice"}, {"id": "76b0f3d9-fa67-4603-a1fb-7578c167849a", "type": "concept", "title": "Legitimacy"}, {"id": "53b91f59-15bd-4655-9f41-41e4e5b331f6", "type": "concept", "title": "Consent of the governed"}, {"id": "76fff20d-c9b0-4b84-a5ac-352401ea6892", "type": "concept", "title": "Public trust"}], "description": "The point is to evaluate what police are asked to do and whether those duties align with democratic values."}, {"id": "b4148a23-c006-4d54-9bdb-287c63a9cb7e", "type": "subtopic", "title": "Policing in the criminal justice system", "children": [{"id": "877e8b33-e9a0-4f2c-a161-a44800d68c73", "type": "concept", "title": "Arrest"}, {"id": "d5f28ef8-2d49-4f04-98f5-791d85348150", "type": "concept", "title": "Charging pipeline"}, {"id": "b1bbdf69-4f35-4a33-81dc-2ac67f8c2c86", "type": "concept", "title": "Prosecution referral"}, {"id": "27b91f12-3ff4-43a9-b5d1-be75eeb27284", "type": "concept", "title": "Diversion"}, {"id": "4b15f78e-f13c-4dbe-ba9d-81a9cb0c07c7", "type": "concept", "title": "Victim services"}, {"id": "00d6cb08-ce5f-4268-9104-1aff31ba5709", "type": "concept", "title": "Corrections handoff"}, {"id": "1c28f094-f7b7-49da-8069-9c99208ff0e8", "type": "concept", "title": "Community safety"}, {"id": "219a9200-561f-497c-a511-2dbc25ad61f9", "type": "concept", "title": "Local governance"}], "description": "Students connect police work to courts, corrections, victims, communities, and public policy."}]}, {"id": "623930f0-d239-486c-94bf-f1eda97d8a22", "type": "topic", "title": "Police Organization and Structure", "description": "American policing is fragmented across local, county, state, tribal, campus, transit, and federal agencies. This unit helps students understand agency structure, jurisdiction, specialization, and governance.", "children": [{"id": "4b6da5f1-982e-4c73-ab14-074d6b00a698", "type": "subtopic", "title": "Agency types and jurisdictions", "children": [{"id": "ea63e4c5-c8cc-43bc-ad0e-db609da4e215", "type": "concept", "title": "Municipal police"}, {"id": "11dbdf15-46c7-4457-b970-6fb8e83d40b8", "type": "concept", "title": "Sheriff's offices"}, {"id": "719acbf6-b66a-40ab-b866-2e18c899fb2f", "type": "concept", "title": "State police"}, {"id": "d8d39e66-9ba5-4ed9-bb6c-58bd63792d81", "type": "concept", "title": "Highway patrol"}, {"id": "9dee792e-f078-4d1c-814e-8f44de1ea2c2", "type": "concept", "title": "Tribal police"}, {"id": "c18c94ed-66dd-49ae-a037-372f3583dd4d", "type": "concept", "title": "Campus police"}, {"id": "75258d1e-48d7-4dce-8e11-e280a5e9c315", "type": "concept", "title": "Transit police"}, {"id": "9887c4ab-0adf-4323-8b06-e0c41441e5a6", "type": "concept", "title": "Federal law enforcement"}], "description": "Students learn why policing authority varies by geography, government level, and legal mandate."}, {"id": "767e6ab9-3db2-49dd-9d24-fec99ce6356e", "type": "subtopic", "title": "Organizational design", "children": [{"id": "4fda7887-c864-4c78-bad6-f30478105532", "type": "concept", "title": "Chain of command"}, {"id": "019f80ea-90f7-421f-8b70-7385e6b321b3", "type": "concept", "title": "Bureaucracy"}, {"id": "55372e3c-aede-4de2-99