update public.learning_paths
set
  title = 'Policing in America',
  goal = 'Policing in America',
  summary = 'Policing in America situates law enforcement as an evolving public authority shaped by local government, race, labor, immigration, social control, reform movements, and public safety demands. Students study history and mission, organization and governance, recruitment and culture, patrol and calls for service, discretion, constitutional limits on stops, searches, arrests, and interrogation, investigations and intelligence, use of force, community and problem-oriented policing, race and legitimacy, accountability, crime data and evidence-based practice, technology and surveillance, specialized contexts and vulnerable populations, officer wellness and ethics, homeland security and federalism, and reform policy design.',
  data = $polcjson${"slug": "policing-in-america", "title": "Policing in America", "description": "Policing in America situates law enforcement as an evolving public authority shaped by local government, race, labor, immigration, social control, reform movements, and public safety demands. Students study history and mission, organization and governance, recruitment and culture, patrol and calls for service, discretion, constitutional limits on stops, searches, arrests, and interrogation, investigations and intelligence, use of force, community and problem-oriented policing, race and legitimacy, accountability, crime data and evidence-based practice, technology and surveillance, specialized contexts and vulnerable populations, officer wellness and ethics, homeland security and federalism, and reform policy design.", "topics": [{"id": "b88b67dc-ff08-4da1-89da-69dad78d4131", "type": "topic", "title": "Foundations and History of Policing in America", "description": "This opening unit situates American policing historically and institutionally. Students learn that policing is not a single agency function but an evolving public authority shaped by local government, race, labor, immigration, social control, reform movements, and public safety demands.", "children": [{"id": "b408d5ae-9e81-43ca-b756-c362432e487e", "type": "subtopic", "title": "Historical development", "children": [{"id": "c4c8fcda-c688-44a2-8b67-ecfca9eafaf9", "type": "concept", "title": "Colonial watch systems"}, {"id": "935870b0-4330-426d-a6c3-c33483544791", "type": "concept", "title": "Slave patrols"}, {"id": "a75657f0-d5e9-4b25-bab8-85f04122db01", "type": "concept", "title": "Municipal police"}, {"id": "7c2b5c77-a5da-455d-a246-b9e44b0b4253", "type": "concept", "title": "Political era"}, {"id": "dddfb846-30c6-4e54-bec3-b73df4384e76", "type": "concept", "title": "Professional era"}, {"id": "0881ec35-880e-4836-88c2-00d070e30af9", "type": "concept", "title": "Reform era"}, {"id": "bf46cea6-8d1b-423b-a80c-d8527426f355", "type": "concept", "title": "Community policing era"}, {"id": "05093e73-1395-4c95-91ac-938c98fb95f1", "type": "concept", "title": "Homeland security era"}], "description": "Students learn how American policing emerged through competing models of order maintenance, professionalization, and community control."}, {"id": "0ccb4f6e-bf24-4099-96cc-aff0c4258829", "type": "subtopic", "title": "Legitimacy and mission", "children": [{"id": "82af5cb4-79d7-4fd3-bed6-b4d3a57c30fa", "type": "concept", "title": "Public order"}, {"id": "243f5cb2-c991-4fe7-8627-bca45e52b725", "type": "concept", "title": "Crime control"}, {"id": "d1c634e6-e719-4249-81f0-231c97a8936e", "type": "concept", "title": "Service role"}, {"id": "b0f096e4-c85e-4e11-b328-5469523232f3", "type": "concept", "title": "Social control"}, {"id": "cbb0c165-3578-4016-b259-9f0950dd21dc", "type": "concept", "title": "Procedural justice"}, {"id": "76b0f3d9-fa67-4603-a1fb-7578c167849a", "type": "concept", "title": "Legitimacy"}, {"id": "53b91f59-15bd-4655-9f41-41e4e5b331f6", "type": "concept", "title": "Consent of the governed"}, {"id": "76fff20d-c9b0-4b84-a5ac-352401ea6892", "type": "concept", "title": "Public trust"}], "description": "The point is to evaluate what police are asked to do and whether those duties align with democratic values."}, {"id": "b4148a23-c006-4d54-9bdb-287c63a9cb7e", "type": "subtopic", "title": "Policing in the criminal justice system", "children": [{"id": "877e8b33-e9a0-4f2c-a161-a44800d68c73", "type": "concept", "title": "Arrest"}, {"id": "d5f28ef8-2d49-4f04-98f5-791d85348150", "type": "concept", "title": "Charging pipeline"}, {"id": "b1bbdf69-4f35-4a33-81dc-2ac67f8c2c86", "type": "concept", "title": "Prosecution referral"}, {"id": "27b91f12-3ff4-43a9-b5d1-be75eeb27284", "type": "concept", "title": "Diversion"}, {"id": "4b15f78e-f13c-4dbe-ba9d-81a9cb0c07c7", "type": "concept", "title": "Victim services"}, {"id": "00d6cb08-ce5f-4268-9104-1aff31ba5709", "type": "concept", "title": "Corrections handoff"}, {"id": "1c28f094-f7b7-49da-8069-9c99208ff0e8", "type": "concept", "title": "Community safety"}, {"id": "219a9200-561f-497c-a511-2dbc25ad61f9", "type": "concept", "title": "Local governance"}], "description": "Students connect police work to courts, corrections, victims, communities, and public policy."}]}, {"id": "623930f0-d239-486c-94bf-f1eda97d8a22", "type": "topic", "title": "Police Organization and Structure", "description": "American policing is fragmented across local, county, state, tribal, campus, transit, and federal agencies. This unit helps students understand agency structure, jurisdiction, specialization, and governance.", "children": [{"id": "4b6da5f1-982e-4c73-ab14-074d6b00a698", "type": "subtopic", "title": "Agency types and jurisdictions", "children": [{"id": "ea63e4c5-c8cc-43bc-ad0e-db609da4e215", "type": "concept", "title": "Municipal police"}, {"id": "11dbdf15-46c7-4457-b970-6fb8e83d40b8", "type": "concept", "title": "Sheriff's offices"}, {"id": "719acbf6-b66a-40ab-b866-2e18c899fb2f", "type": "concept", "title": "State police"}, {"id": "d8d39e66-9ba5-4ed9-bb6c-58bd63792d81", "type": "concept", "title": "Highway patrol"}, {"id": "9dee792e-f078-4d1c-814e-8f44de1ea2c2", "type": "concept", "title": "Tribal police"}, {"id": "c18c94ed-66dd-49ae-a037-372f3583dd4d", "type": "concept", "title": "Campus police"}, {"id": "75258d1e-48d7-4dce-8e11-e280a5e9c315", "type": "concept", "title": "Transit police"}, {"id": "9887c4ab-0adf-4323-8b06-e0c41441e5a6", "type": "concept", "title": "Federal law enforcement"}], "description": "Students learn why policing authority varies by geography, government level, and legal mandate."}, {"id": "767e6ab9-3db2-49dd-9d24-fec99ce6356e", "type": "subtopic", "title": "Organizational design", "children": [{"id": "4fda7887-c864-4c78-bad6-f30478105532", "type": "concept", "title": "Chain of command"}, {"id": "019f80ea-90f7-421f-8b70-7385e6b321b3", "type": "concept", "title": "Bureaucracy"}, {"id": "55372e3c-aede-4de2-99ed-574dc269506e", "type": "concept", "title": "Command staff"}, {"id": "026fcfcd-9356-4514-82a0-4820d83411a5", "type": "concept", "title": "Patrol division"}, {"id": "4c35b02e-92db-481f-805a-ee13623bac72", "type": "concept", "title": "Investigations division"}, {"id": "10e39f34-8b92-4f9e-91c3-927a01a096fa", "type": "concept", "title": "Specialized units"}, {"id": "6f9ca453-26a1-49f0-83c3-9f14fd0a8c3f", "type": "concept", "title": "Span of control"}, {"id": "d6d183fe-c839-422c-978d-3657ee927953", "type": "concept", "title": "Decentralization"}], "description": "Students examine how structure affects communication, discretion, supervision, and accountability."}, {"id": "dddaf8d3-3219-4243-8f16-efc8c50c70c3", "type": "subtopic", "title": "Budgets and governance", "children": [{"id": "ad96244c-9903-4c27-a45f-fcea9af08a67", "type": "concept", "title": "Municipal budgets"}, {"id": "eaad50b7-65df-4883-b07e-a677d29acd64", "type": "concept", "title": "Grant funding"}, {"id": "05dcea87-8526-406f-b0f1-753b8322abca", "type": "concept", "title": "Police unions"}, {"id": "65de2e5a-16c2-4c6b-adb7-1b512fdd696f", "type": "concept", "title": "Civil service"}, {"id": "9d2d55ec-9b96-4fbb-8aab-08ac6ea6b0df", "type": "concept", "title": "Collective bargaining"}, {"id": "9c99f3f0-aa60-4019-bcbe-6117667a8c57", "type": "concept", "title": "City councils"}, {"id": "ca4b2a37-6145-476c-b772-b1e242357b3f", "type": "concept", "title": "Mayors"}, {"id": "5b0b16f4-04e7-481c-82aa-db1a40337b26", "type": "concept", "title": "Police commissions"}], "description": "The goal is to connect police priorities to local politics, funding, labor relations, and public oversight."}]}, {"id": "6ddc8291-d0ea-42e0-a70b-006eb228a5b5", "type": "topic", "title": "Recruitment, Training, and Police Culture", "description": "Who becomes a police officer, how they are trained, and what norms they learn shape every other policing outcome. This unit treats culture as both a source of professional identity and a barrier to reform when norms go wrong.", "children": [{"id": "f848ea5b-35a3-43e8-be18-fecc9f9b57be", "type": "subtopic", "title": "Recruitment and selection", "children": [{"id": "12024f71-bf2f-4a1f-a652-4bc617563e6a", "type": "concept", "title": "Minimum qualifications"}, {"id": "3748964e-fe68-424c-8cd9-15438386c0a8", "type": "concept", "title": "Background investigations"}, {"id": "5937eb8e-79a3-4fdf-96d1-54cada0e884f", "type": "concept", "title": "Psychological screening"}, {"id": "dc3d7a18-5380-453a-8a55-6caa664d1ad2", "type": "concept", "title": "Physical standards"}, {"id": "fef852bb-37fa-4c3e-9cc6-0ab0fbab81e9", "type": "concept", "title": "Lateral hiring"}, {"id": "01e8e98c-565e-43d5-ad07-8f61f17ecc98", "type": "concept", "title": "Diversity recruitment"}, {"id": "2dab8898-6bea-47ce-afc3-f2185944df7c", "type": "concept", "title": "Hiring and retention"}, {"id": "6638e440-0ee2-4b5d-a1e5-e1371e11511c", "type": "concept", "title": "Moral character"}], "description": "Students learn the personnel pipeline and why hiring standards matter for legitimacy and service quality."}, {"id": "48bad038-625f-4405-9c3d-7886cd3edc0b", "type": "subtopic", "title": "Training systems", "children": [{"id": "367de92e-0bdb-4169-b646-7dc703ff8fe8", "type": "concept", "title": "Training academies"}, {"id": "6ca73f2c-a377-490f-a575-dbdfbaebe4ea", "type": "concept", "title": "Field training officer"}, {"id": "adb2a497-802b-41b0-9694-795be606e80c", "type": "concept", "title": "Scenario-based training"}, {"id": "3a36a94d-209d-42d2-ba89-600d2057d615", "type": "concept", "title": "Legal updates"}, {"id": "344d39a2-55d4-4e83-88e5-aae40ada290d", "type": "concept", "title": "De-escalation training"}, {"id": "c4260b35-23c0-4854-8abb-ccfeab6b1de9", "type": "concept", "title": "Implicit bias training"}, {"id": "a961ca2e-565c-4f87-80b8-fff5acf0550f", "type": "concept", "title": "Crisis intervention training"}, {"id": "f65ceb6b-bdb3-4eb3-a134-1ca4e7e8dc60", "type": "concept", "title": "In-service training"}], "description": "Students examine how academy, field, and continuing training shape legal knowledge and tactical judgment."}, {"id": "f6cd7ea4-68f1-4828-bad4-8ff11b9fc22d", "type": "subtopic", "title": "Police culture", "children": [{"id": "6ee465f8-de14-4a3d-baa0-c4cb8ac68587", "type": "concept", "title": "Working personality"}, {"id": "6a50d8f4-1eca-4bdf-b95d-735291c95733", "type": "concept", "title": "Solidarity"}, {"id": "b22d5384-e964-4293-9aeb-72ba9b77dcf7", "type": "concept", "title": "Cynicism"}, {"id": "3bc5c5ea-3463-48aa-b254-9acb4cb7b710", "type": "concept", "title": "Danger imperative"}, {"id": "680e6e41-b319-4a74-a696-4f93b27b11ac", "type": "concept", "title": "Code of silence"}, {"id": "75ef61b9-bc17-4436-ab81-9fd0dbba35db", "type": "concept", "title": "Service ethos"}, {"id": "b82f06e1-ed6b-47a3-ac27-8a94471081c2", "type": "concept", "title": "Warrior mindset"}, {"id": "c67be3a0-e4d8-4b27-bfc4-64c824580e44", "type": "concept", "title": "Guardian mindset"}], "description": "The point is to understand shared norms without reducing officers to stereotypes."}]}, {"id": "ca0971aa-48c3-4fe6-b926-5c87a8fec47c", "type": "topic", "title": "Patrol, Calls for Service, and Everyday Operations", "description": "Patrol is the visible core of policing. Students learn how routine calls, traffic stops, order maintenance, report writing, and dispatch decisions shape public contact more than dramatic crime scenes do.", "children": [{"id": "1ea13768-61e4-4bd9-a57e-231598c3d17e", "type": "subtopic", "title": "Patrol strategies", "children": [{"id": "494a61bc-40d1-4027-bbb1-25d9c9cbd6c4", "type": "concept", "title": "Preventive patrol"}, {"id": "812992cc-afa3-4baf-a707-bc4a802910f8", "type": "concept", "title": "Directed patrol"}, {"id": "cba903c8-79d7-4818-96f1-b023af23821a", "type": "concept", "title": "Hot spots policing"}, {"id": "2fc4632b-af8b-49ca-b4e5-f9b98335cdbf", "type": "concept", "title": "Foot patrol"}, {"id": "0fbd44a5-d415-4416-8e5f-258647edd8fa", "type": "concept", "title": "Vehicle patrol"}, {"id": "81664f3b-e58b-4c9e-935a-dea546799c4b", "type": "concept", "title": "Bike patrol"}, {"id": "6769d762-1fc5-477a-96f4-35b1321f1586", "type": "concept", "title": "Differential response"}, {"id": "fcbe4840-783b-4401-bf5b-404a29cf9329", "type": "concept", "title": "Saturation patrol"}], "description": "Students compare the purposes and evidence behind different approaches to patrol deployment."}, {"id": "8d95d1ea-4b2e-4f94-94a2-850656ebd447", "type": "subtopic", "title": "Calls for service", "children": [{"id": "43061290-de33-4d31-871f-f4624682a63c", "type": "concept", "title": "911 calls"}, {"id": "65afe3bd-4fcb-4b13-ad71-42f3c09943bc", "type": "concept", "title": "Computer-aided dispatch"}, {"id": "6e5b5a6f-5938-4c48-9ad5-68e1ae57243a", "type": "concept", "title": "Priority codes"}, {"id": "febf15ba-9a7e-40ed-b3f7-5aa5cf4a1b33", "type": "concept", "title": "Response time"}, {"id": "90d2f268-fa5c-4742-b6d3-8f6ffd8fdafe", "type": "concept", "title": "Domestic disturbance"}, {"id": "e520a40c-a16a-4faf-88c0-9ce1e26d746d", "type": "concept", "title": "Noise complaints"}, {"id": "60e2735e-6230-4249-857c-4dbc3279076f", "type": "concept", "title": "Welfare checks"}, {"id": "762f5435-7c15-49c5-b260-f608381bf339", "type": "concept", "title": "Mental health calls"}], "description": "Students learn how police workload is produced by community needs, dispatch categories, and service expectations."}, {"id": "2cf9b65f-75d8-44d3-bee7-39de2f8c1195", "type": "subtopic", "title": "Operational documentation", "children": [{"id": "454bacc9-e7f8-4b29-8603-db0512fb4de0", "type": "concept", "title": "Incident reports"}, {"id": "7f3787b9-b285-4be3-ab7e-817abc097138", "type": "concept", "title": "Field interview cards"}, {"id": "7800e2f6-053b-490e-b1a8-1e2757c1f470", "type": "concept", "title": "CAD data"}, {"id": "05410365-89d4-4c36-9a05-b8f5e58cd4ce", "type": "concept", "title": "Body-worn camera tags"}, {"id": "2631e17d-e334-442d-aa20-390094029897", "type": "concept", "title": "Supplemental reports"}, {"id": "180e8202-6b11-4e28-a28e-d97745c85007", "type": "concept", "title": "Evidence logs"}, {"id": "f466986e-e3ac-41a1-9526-75723e94b7a0", "type": "concept", "title": "Supervisor review"}, {"id": "ae41223a-12e4-4784-8092-0a3a4408d938", "type": "concept", "title": "Records management systems"}], "description": "The goal is to understand how routine paperwork becomes legal, administrative, and accountability evidence."}]}, {"id": "36e7c01a-11ae-4e9a-9e02-6e94a01b6b43", "type": "topic", "title": "Police Discretion and Decision-Making", "description": "Police discretion is unavoidable because officers make rapid choices under uncertainty. This unit teaches students to distinguish necessary judgment from arbitrary, biased, or unlawful decision-making.", "children": [{"id": "514122df-d984-4d6a-9633-c8ff2354f4ee", "type": "subtopic", "title": "Sources of discretion", "children": [{"id": "31861130-18e2-43e0-8cf6-04afdd892502", "type": "concept", "title": "Stop decisions"}, {"id": "f51dc509-0fd8-489b-8651-edfe759e98e3", "type": "concept", "title": "Warning versus citation"}, {"id": "9d5a61d1-0d46-4521-a3b4-b6ed02ee232a", "type": "concept", "title": "Arrest versus release"}, {"id": "0124ebc9-9b7d-40bd-9892-684c1da9373a", "type": "concept", "title": "Search decisions"}, {"id": "728c6828-5a05-4359-8e71-244fe96eec86", "type": "concept", "title": "Use-of-force decisions"}, {"id": "c824e934-32bc-43b6-a858-ae9065bb73b2", "type": "concept", "title": "Referral to services"}, {"id": "c9450bac-6f44-40df-8439-8747b6ff068a", "type": "concept", "title": "Diversion"}, {"id": "58800ab8-7ff9-47fc-bc86-f91f9cddeb81", "type": "concept", "title": "Report classification"}], "description": "Students learn where discretion appears in ordinary police work."}, {"id": "bdce6f4c-05f5-4c31-9834-9a693b94994d", "type": "subtopic", "title": "Influences on decisions", "children": [{"id": "204eb996-3282-4045-9562-9cc7edbb6d40", "type": "concept", "title": "Legal standards"}, {"id": "f39bb68b-697f-42fa-9a30-4b4282745068", "type": "concept", "title": "Department policy"}, {"id": "56685f18-e15b-40c1-8ee3-0bb92dce4ffe", "type": "concept", "title": "Peer norms"}, {"id": "d62a8f3e-f5c2-411a-917a-fb9c0c7e7af1", "type": "concept", "title": "Supervisor expectations"}, {"id": "3554b4a6-d184-4c0e-9f5c-2105a0d5b29e", "type": "concept", "title": "Neighborhood context"}, {"id": "1c85cd9c-6a21-4f65-9297-f0d3a530afd4", "type": "concept", "title": "Complainant preferences"}, {"id": "c752d527-c997-4f7c-ae3b-d6d285fe533f", "type": "concept", "title": "Implicit bias"}, {"id": "57c97d89-ff34-43d2-ae71-1e4c06a5a902", "type": "concept", "title": "Officer experience"}], "description": "The point is to analyze how law, policy, culture, environment, and individual perception shape officer choices."}, {"id": "87c457fd-0986-45b0-a604-32cdc614043c", "type": "subtopic", "title": "Controlling discretion", "children": [{"id": "c29a5b04-4216-4f25-bdf0-b88039ecdc7a", "type": "concept", "title": "Written policy"}, {"id": "35889bc2-11a7-483b-bcea-8b7a61c7bc89", "type": "concept", "title": "Training"}, {"id": "174d56de-9816-4c53-9909-2027b5557810", "type": "concept", "title": "Supervision"}, {"id": "f3ae81ad-0dae-46c3-be78-d315142b76c8", "type": "concept", "title": "Early intervention systems"}, {"id": "b2d6f4d6-e3b9-48ac-bdda-af52f70be7b5", "type": "concept", "title": "Audits"}, {"id": "31fb9848-7065-41ae-9b40-bedebf5c6629", "type": "concept", "title": "Body-worn camera review"}, {"id": "3551cc99-8383-4048-b13d-9aeddd532942", "type": "concept", "title": "Data dashboards"}, {"id": "57eab008-8620-404c-9e64-1cb98349f244", "type": "concept", "title": "Disciplinary consistency"}], "description": "Students evaluate methods for guiding discretion without eliminating practical judgment."}]}, {"id": "0df01e23-e347-4daa-8b7d-a6a08a837bcc", "type": "topic", "title": "Constitutional Policing: Stops, Searches, Arrests, and Interrogation", "description": "Police power is limited by constitutional rules. Students learn the core Fourth, Fifth, Sixth, and Fourteenth Amendment doctrines that govern encounters, searches, arrests, interrogation, and evidence.", "children": [{"id": "6bcc0bf3-bb8d-47e5-95f9-83434cbd27fa", "type": "subtopic", "title": "Fourth Amendment encounters", "children": [{"id": "9949b3ea-d589-4cce-b10b-2d5c8c9787d0", "type": "concept", "title": "Consensual encounter"}, {"id": "7fab5768-f76a-439d-9648-3a37d3cf5ac2", "type": "concept", "title": "Reasonable suspicion"}, {"id": "75eda8bf-83c2-4124-90aa-a41add5505e2", "type": "concept", "title": "Terry stop"}, {"id": "7660c423-e77c-4e95-941b-e1e012c5c329", "type": "concept", "title": "Frisk"}, {"id": "3f784c49-31ff-48ac-83f6-7c7e07048c52", "type": "concept", "title": "Probable cause"}, {"id": "475aafec-8319-48cc-8d94-8968cfbe52b5", "type": "concept", "title": "Arrest"}, {"id": "a8f33d26-a059-40a6-b411-480f0aecb7df", "type": "concept", "title": "Search warrant"}, {"id": "af8f178c-d30b-4e06-9339-23c6dba30c5b", "type": "concept", "title": "Exigent circumstances"}], "description": "Students learn the legal thresholds that separate conversation, detention, arrest, search, and seizure."}, {"id": "7e46be29-8118-4553-9524-1c693f3d2811", "type": "subtopic", "title": "Search and seizure contexts", "children": [{"id": "00ce4779-253c-4d6b-9e0e-17e9806e5ff5", "type": "concept", "title": "Traffic stops"}, {"id": "ce74d4d3-746a-4923-a750-9f22f8e01d26", "type": "concept", "title": "Vehicle searches"}, {"id": "5566befb-a0de-4628-92b0-6277be1baddd", "type": "concept", "title": "Consent searches"}, {"id": "9b15a594-a75b-4447-b2d3-61e8b2708dfc", "type": "concept", "title": "Plain view"}, {"id": "524c8ac5-4f8f-4ea2-8734-e4fa80532ad1", "type": "concept", "title": "Search incident to arrest"}, {"id": "e5dc17c7-4f6f-4045-a82f-ebdd8bcba7f8", "type": "concept", "title": "Inventory search"}, {"id": "094e8a70-66b0-4597-ad51-5f2a44b8544b", "type": "concept", "title": "Stop-and-frisk"}, {"id": "9e3580f9-d84e-42f4-84f2-edfe390e9f4b", "type": "concept", "title": "Digital searches"}], "description": "Students apply doctrine to common policing scenarios."}, {"id": "d5106329-13f9-4faf-9459-043e801e5c93", "type": "subtopic", "title": "Interrogation and due process", "children": [{"id": "5e43ab94-1ab8-4673-829d-60296d9639bb", "type": "concept", "title": "Miranda warnings"}, {"id": "f983d72b-c4fb-44ad-a5d4-bba3fcb63ce5", "type": "concept", "title": "Custodial interrogation"}, {"id": "b96ab370-89d6-485d-a0ee-656e79c179f0", "type": "concept", "title": "Voluntariness"}, {"id": "65fe1d99-5376-4fb5-9b0e-240012f1f345", "type": "concept", "title": "Right to counsel"}, {"id": "bbf50cc8-b81c-4cf8-b7a7-48d8e4fa630a", "type": "concept", "title": "Waiver"}, {"id": "1084f3fb-14bf-4cd6-accd-e690a2861a18", "type": "concept", "title": "Identification procedures"}, {"id": "f8888df8-59fb-4e07-bf82-c7b7b22a3c99", "type": "concept", "title": "Due process"}, {"id": "d30710a7-50d0-4e0f-b297-21e13b3a54f1", "type": "concept", "title": "Exclusionary rule"}], "description": "Students connect policing practice to constitutional protections against coercion and unreliable statements."}]}, {"id": "ab1cf1e1-ca54-46ba-ad93-35b1df093f29", "type": "topic", "title": "Investigations, Crime Analysis, and Intelligence-Led Policing", "description": "Investigative policing converts information into cases, patterns, and prevention strategies. This unit covers detective work, crime analysis, intelligence, and the safeguards needed when information becomes power.", "children": [{"id": "1a8f1083-a56b-44ce-9013-7a8679c3208d", "type": "subtopic", "title": "Investigative process", "children": [{"id": "22cbca29-b781-4fcc-b598-f93b17552cee", "type": "concept", "title": "Preliminary investigation"}, {"id": "a0563405-693b-4917-9845-da6add1157cd", "type": "concept", "title": "Follow-up investigation"}, {"id": "f79e0626-360d-4cd2-9102-24b930c0d65e", "type": "concept", "title": "Witness interviews"}, {"id": "7b9bd205-4cc2-4e37-88a1-d5ece4ef372c", "type": "concept", "title": "Victim interviews"}, {"id": "8d45c917-a8d9-4cfd-8f37-3bb68a803534", "type": "concept", "title": "Suspect interviews"}, {"id": "e84358bf-6a04-4553-80fd-b87cba35d9ff", "type": "concept", "title": "Evidence collection"}, {"id": "eda69b4d-7ac8-4462-a7d9-2bce3cb0b1ed", "type": "concept", "title": "Case screening"}, {"id": "e7adef99-4dc9-4af0-b02c-bab088e13810", "type": "concept", "title": "Clearance rates"}], "description": "Students learn how cases move from initial report to clearance or closure."}, {"id": "813d2c85-3069-4f1e-bc67-c8188554d9bb", "type": "subtopic", "title": "Crime analysis", "children": [{"id": "6da88376-9499-4d53-8c3a-1e405d578b63", "type": "concept", "title": "Crime mapping"}, {"id": "607d3ad0-b90f-4a06-94d7-90f228bf1f78", "type": "concept", "title": "Hot spots"}, {"id": "96a04d47-951d-4f65-acae-0ee8eea0b00f", "type": "concept", "title": "Temporal analysis"}, {"id": "39f23948-52a0-4944-b44f-ca54803c161b", "type": "concept", "title": "Repeat victimization"}, {"id": "ba4f1d4f-00be-4276-95a2-fdba2a9e6144", "type": "concept", "title": "Repeat offenders"}, {"id": "85ccf85a-c53a-4152-af27-2c8daf371d31", "type": "concept", "title": "Problem analysis triangle"}, {"id": "13a24fc5-b19b-40a5-a0cf-005a5c36a194", "type": "concept", "title": "CompStat"}, {"id": "629f920f-92f1-4ae1-b21b-ae60c81f6884", "type": "concept", "title": "LEARCAT"}], "description": "Students learn how agencies identify patterns, allocate resources, and evaluate public safety problems."}, {"id": "1b85aa33-a41e-4ac5-8574-a623d713e41e", "type": "subtopic", "title": "Intelligence and safeguards", "children": [{"id": "eaec1110-59c7-4af3-9bec-bc33e3f7f402", "type": "concept", "title": "Criminal intelligence"}, {"id": "aeaa5e9a-0ee4-485a-bec9-7f30435319d1", "type": "concept", "title": "Fusion centers"}, {"id": "eab1a01c-eb36-4ff3-9d37-db2a90d21289", "type": "concept", "title": "Suspicious activity reports"}, {"id": "84e33487-0e9e-4248-93ae-af330fb01d99", "type": "concept", "title": "Gang databases"}, {"id": "f45c4e0a-fbc2-466b-afbe-dec9c5e43861", "type": "concept", "title": "Threat assessment"}, {"id": "52f28518-6765-449a-acd0-0734d8419f83", "type": "concept", "title": "Data quality"}, {"id": "27a9fec1-c2f9-4b31-98bf-9e9c0a458856", "type": "concept", "title": "Privacy"}, {"id": "e515773a-50c1-48e8-9904-1ec6fd8bbaac", "type": "concept", "title": "Civil liberties"}], "description": "The goal is to evaluate intelligence work through legality, accuracy, privacy, and civil liberties."}]}, {"id": "7de2901a-f884-4c74-ab49-39590a8ae324", "type": "topic", "title": "Use of Force, De-Escalation, and Officer Safety", "description": "Use of force is one of the most consequential areas of policing for community trust, officer safety, and constitutional accountability. Students study law, policy, tactics, reporting, and prevention.", "children": [{"id": "b5120d31-bfda-41f0-93c3-c6ef68123b58", "type": "subtopic", "title": "Force law and policy", "children": [{"id": "72538750-aeca-4f7f-895b-f0009a08b2c4", "type": "concept", "title": "Objective reasonableness"}, {"id": "6bd5a963-7cf4-4207-9a8a-52585637abc7", "type": "concept", "title": "Graham v. Connor"}, {"id": "f01c998d-c9c2-40c0-a0cd-5fd7af38f3bb", "type": "concept", "title": "Tennessee v. Garner"}, {"id": "cb6e558c-8c87-4682-abd0-6a90a966690f", "type": "concept", "title": "Deadly force"}, {"id": "6a9e00a9-b1d7-4f3d-8054-0a0f773f45ec", "type": "concept", "title": "Less-lethal force"}, {"id": "1b81debc-b723-47e5-87f3-077d459e2038", "type": "concept", "title": "Duty to intervene"}, {"id": "d112f765-a1f6-423a-acfa-b385fbd10986", "type": "concept", "title": "Warning before shooting"}, {"id": "4605a7b6-fcde-4bf3-941d-9929a12fa569", "type": "concept", "title": "Force continuum"}], "description": "Students learn the legal standards and policy frameworks that govern force."}, {"id": "b3b56b02-d95b-420d-ba30-42d8c4e73f7e", "type": "subtopic", "title": "De-escalation and tactics", "children": [{"id": "c6e2cf36-4223-4019-bd1f-ae8c0ba131ef", "type": "concept", "title": "De-escalation"}, {"id": "b9b8f287-dd88-4314-af28-12da312bf65e", "type": "concept", "title": "Crisis communication"}, {"id": "a9771cea-25fd-49a5-9c11-8ade56141349", "type": "concept", "title": "Distance and cover"}, {"id": "db7d0a66-7645-492e-a8b3-c9f20087927e", "type": "concept", "title": "Tactical repositioning"}, {"id": "b361f3fa-9d18-4152-a56e-25d0abe237eb", "type": "concept", "title": "Containment"}, {"id": "b6802039-9486-4bf4-b16c-bccb1b637c5e", "type": "concept", "title": "Critical decision-making model"}, {"id": "25611256-5576-4d8c-aa40-7cab1aef2b19", "type": "concept", "title": "Scenario training"}, {"id": "34e7635a-00e9-4f20-b761-ef5a78f053d3", "type": "concept", "title": "After-action review"}], "description": "The point is to understand how time, distance, communication, and tactical positioning can reduce harm."}, {"id": "87221647-a2bc-4575-8e92-00d72caa279b", "type": "subtopic", "title": "Safety and force accountability", "children": [{"id": "a1978ea5-e889-44b0-a797-47da5d851a63", "type": "concept", "title": "Officer safety"}, {"id": "24f1970b-dd5f-4259-8117-ccb9f3e4ff38", "type": "concept", "title": "Body armor"}, {"id": "7a74a26b-b60f-4948-8065-7fe9c4ce08cd", "type": "concept", "title": "Vehicle stops"}, {"id": "53d5f232-d786-4205-bcb3-709c5f6e0b52", "type": "concept", "title": "Ambush risk"}, {"id": "5f006008-07ea-4e8d-82ac-42bcd17d78ee", "type": "concept", "title": "Use-of-force reports"}, {"id": "3d24612b-c56e-4a3d-a90c-77af3c045768", "type": "concept", "title": "Supervisor review"}, {"id": "2975a493-c4f6-4c12-861e-6b4ede5d5512", "type": "concept", "title": "Force review boards"}, {"id": "6f170731-49de-49f7-b15a-956822947053", "type": "concept", "title": "Public reporting"}], "description": "Students connect officer safety, community safety, and transparent review."}]}, {"id": "0f4e2d2b-5ea4-4743-8427-b341ac301eff", "type": "topic", "title": "Community Policing and Problem-Oriented Policing", "description": "Community policing and problem-oriented policing ask agencies to build partnerships and solve recurring problems rather than merely respond to calls. Students learn both the promise and implementation challenges of these approaches.", "children": [{"id": "07bf04f5-9025-4d05-93f4-c2d0c7f079da", "type": "subtopic", "title": "Community policing principles", "children": [{"id": "cee73e67-17aa-4ef2-ba12-fd1390b9c089", "type": "concept", "title": "Partnerships"}, {"id": "7eea1531-2058-4286-ba22-471ea22e3161", "type": "concept", "title": "Organizational transformation"}, {"id": "31f8daad-30a1-489d-9425-00c783e7a8c3", "type": "concept", "title": "Problem solving"}, {"id": "0b5e7aa2-eee1-49dc-bdb5-8406b41efba8", "type": "concept", "title": "Beat ownership"}, {"id": "0e93c10c-3320-4c5b-b4c6-d4d448f98ea4", "type": "concept", "title": "Community meetings"}, {"id": "e1153ff1-6f9e-4343-88e1-30f0ecc2785e", "type": "concept", "title": "Co-production of safety"}, {"id": "6c1578e9-62d7-4b37-a658-afdaf0c5908c", "type": "concept", "title": "Trust-building"}, {"id": "96b70287-287a-42a3-b0d5-c12e75b9d22d", "type": "concept", "title": "Community advisory groups"}], "description": "Students learn how police-community partnerships are built and sustained."}, {"id": "e4341dbd-dd2b-4d8d-ac69-5a578c4f9398", "type": "subtopic", "title": "Problem-oriented policing", "children": [{"id": "8a52f819-df98-48c5-81bf-d9b448264827", "type": "concept", "title": "SARA model"}, {"id": "c14dc50d-6654-4908-8b62-81457e5b5b8c", "type": "concept", "title": "Scanning"}, {"id": "0c685025-1764-4cb9-b389-987e8c6f377b", "type": "concept", "title": "Analysis"}, {"id": "7834819c-44fb-4060-834d-03854260d850", "type": "concept", "title": "Response"}, {"id": "bd476731-2b56-4a9e-8b39-83f53073dc70", "type": "concept", "title": "Assessment"}, {"id": "fab3eb11-1053-4884-8c51-22a2ef30f115", "type": "concept", "title": "Problem analysis triangle"}, {"id": "e06ec3d3-3690-4ef6-a7f1-152708acc032", "type": "concept", "title": "Repeat places"}, {"id": "d86b1372-6bff-4706-8d74-1104b319668e", "type": "concept", "title": "Repeat victims"}, {"id": "e7f3df48-5bac-43f2-8e07-a113f58c42a6", "type": "concept", "title": "Repeat offenders"}], "description": "Students practice the analytic cycle used to define, respond to, and assess recurring public safety problems."}, {"id": "1d690d60-16a3-4081-94ff-63102c208360", "type": "subtopic", "title": "Implementation realities", "children": [{"id": "948b6047-351c-445a-aeb2-d79f61b03867", "type": "concept", "title": "Mission drift"}, {"id": "a6f2def1-afd1-4a4b-89b4-bbddac610733", "type": "concept", "title": "Performance metrics"}, {"id": "c553344b-58a1-43e0-b4e7-7d9e521de8b8", "type": "concept", "title": "Officer buy-in"}, {"id": "e45cc8a9-9570-4e78-95fb-90663d61858b", "type": "concept", "title": "Community representation"}, {"id": "112790ec-fd44-4d45-a9bc-af42be6d51fc", "type": "concept", "title": "Sustained engagement"}, {"id": "0a3adc03-aef2-41d4-ab93-68ee3790db28", "type": "concept", "title": "Resource constraints"}, {"id": "14a4a34e-49a3-4282-aa62-f025d09c3572", "type": "concept", "title": "Evaluation"}, {"id": "ab506eac-061a-4461-b58f-87bae9f90cee", "type": "concept", "title": "Procedural justice"}], "description": "The goal is to identify why community policing can become symbolic unless staffing, incentives, and accountability align."}]}, {"id": "91837411-5804-4a7d-8195-f6f44300e677", "type": "topic", "title": "Police-Community Relations, Race, and Legitimacy", "description": "American policing cannot be understood without race, inequality, and contested legitimacy. This unit gives students language and evidence for analyzing disparities, community experience, and trust.", "children": [{"id": "2400026b-9eff-4887-8871-8bc0d84a76b0", "type": "subtopic", "title": "Historical and structural context", "children": [{"id": "8da8ca79-466b-4a60-97f4-94d3b5f5ecb9", "type": "concept", "title": "Slave patrol legacy"}, {"id": "35034a3d-8140-47a3-869c-4968e08c569d", "type": "concept", "title": "Jim Crow enforcement"}, {"id": "503601d5-339d-449a-abc4-942fec362673", "type": "concept", "title": "Civil rights protests"}, {"id": "6e83c3fb-6fee-48f2-843d-07fae9ace86e", "type": "concept", "title": "War on drugs"}, {"id": "a45904c7-3ac5-4257-aec9-5118d9afbddb", "type": "concept", "title": "Broken windows policing"}, {"id": "246017a0-44f1-4a73-b3b6-b9602ac80cb0", "type": "concept", "title": "Immigration enforcement"}, {"id": "75da5d70-e8a4-4b7a-8bd4-d76873ce58c1", "type": "concept", "title": "Racial profiling"}, {"id": "a371fdd3-eeb0-4159-8f6a-5e6640dd0d78", "type": "concept", "title": "Mass incarceration"}], "description": "Students connect present policing debates to historical patterns of law enforcement and social control."}, {"id": "b081257e-ea6e-453d-a872-65eaa2465029", "type": "subtopic", "title": "Disparity and lived experience", "children": [{"id": "cbb76e82-a1db-4567-8512-8c06458892f6", "type": "concept", "title": "Traffic stop disparities"}, {"id": "c7bc467c-0a52-4ff8-823a-8a135c0efd39", "type": "concept", "title": "Pedestrian stops"}, {"id": "48c2e792-4562-443a-a0d7-f6b71845597c", "type": "concept", "title": "Search rates"}, {"id": "1c9fd1fa-3b0e-4039-9c0a-dbad01a25f6b", "type": "concept", "title": "Arrest disparities"}, {"id": "ae347b88-e77d-4d24-9543-427a671642fb", "type": "concept", "title": "Use-of-force disparities"}, {"id": "a702fdf3-ec14-49fe-a073-11e77f30e3f2", "type": "concept", "title": "Neighborhood surveillance"}, {"id": "421f1e03-4ce9-4291-bdf0-ef8a2a7e624f", "type": "concept", "title": "Victim trust"}, {"id": "47d6c5c2-6944-4570-97b6-5597b2a90ab8", "type": "concept", "title": "Fear of crime"}], "description": "Students examine how policing outcomes vary across race, ethnicity, class, gender, age, and place."}, {"id": "578b1755-b6be-44ec-b9ec-8d361cb058e9", "type": "subtopic", "title": "Legitimacy and repair", "children": [{"id": "5872a178-8a48-4c02-9b03-17f43524ba50", "type": "concept", "title": "Procedural justice"}, {"id": "158d0a86-75a5-423a-b011-0fb95ce7bc08", "type": "concept", "title": "Voice"}, {"id": "78d6db18-b211-4bd2-ac07-a2e4bec9a54e", "type": "concept", "title": "Neutrality"}, {"id": "647f6016-0cf5-46ea-bc8d-6a6b7a79a303", "type": "concept", "title": "Respect"}, {"id": "19b6c955-b362-4f13-9af1-36900636fc70", "type": "concept", "title": "Trustworthy motives"}, {"id": "45a6463c-eb90-49b0-8682-2e6c36e8b69a", "type": "concept", "title": "Truth-telling"}, {"id": "28bc3eb4-c11d-4f98-a41d-84e4fa3dcab2", "type": "concept", "title": "Reconciliation"}, {"id": "9c994967-76fd-4d52-9aff-0b3d28c1643c", "type": "concept", "title": "Community accountability"}], "description": "The goal is to study how agencies can rebuild trust after harm."}]}, {"id": "ef480e63-6266-47c2-950b-e353b426424a", "type": "topic", "title": "Police Accountability, Oversight, and Misconduct", "description": "Accountability systems determine whether police power remains lawful, transparent, and legitimate. Students learn internal discipline, civilian oversight, civil litigation, pattern-or-practice enforcement, and transparency tools.", "children": [{"id": "54394153-ae43-4727-8235-24c8ec9bbc87", "type": "subtopic", "title": "Internal accountability", "children": [{"id": "756f01f2-cd0e-4613-9187-ada9ec0f8b3b", "type": "concept", "title": "Internal affairs"}, {"id": "5e0c600b-30cb-46eb-a334-b43d9ef44f20", "type": "concept", "title": "Complaint intake"}, {"id": "79f6d7ae-fe67-45ec-b7bb-9241131ba4b1", "type": "concept", "title": "Administrative investigation"}, {"id": "9bb26a0e-e6bc-4dfe-be23-7fdfa9a78fd2", "type": "concept", "title": "Sustained findings"}, {"id": "83b52d74-d9c3-4fe5-8c49-35979b411786", "type": "concept", "title": "Discipline matrix"}, {"id": "5bba1d9c-191b-4107-b4f3-8e9a713fb65c", "type": "concept", "title": "Early intervention systems"}, {"id": "4699b8a1-39d3-43ce-abb0-70d2f8270179", "type": "concept", "title": "Supervisor liability"}, {"id": "df4dc683-364a-4b6e-8238-256d94bcbc72", "type": "concept", "title": "Integrity tests"}], "description": "Students learn how agencies identify and respond to misconduct inside the organization."}, {"id": "05112812-9aaa-45bb-8ee7-cf9284f680a6", "type": "subtopic", "title": "External oversight", "children": [{"id": "10ae78f0-55d7-46b4-b7a8-be0e0fcc880c", "type": "concept", "title": "Civilian review boards"}, {"id": "acc2ab2c-5e81-4eeb-93a7-a2b6c33717c5", "type": "concept", "title": "Inspector general"}, {"id": "ffba683d-e906-4023-8ed3-8da290bffecc", "type": "concept", "title": "Auditor model"}, {"id": "d7312fb6-263a-4ef3-887b-d0d9059d4320", "type": "concept", "title": "Monitor model"}, {"id": "0d70d57e-95e1-4bcd-9312-79a045dafac2", "type": "concept", "title": "Consent decrees"}, {"id": "99c14213-c01a-4d51-8824-deb7a9ce79d5", "type": "concept", "title": "Pattern-or-practice investigations"}, {"id": "6e604a5d-f938-4024-8806-5e879f89dd3a", "type": "concept", "title": "Public records"}, {"id": "7a53b58c-8e07-4142-bfa8-0f5142dc454d", "type": "concept", "title": "Open data"}], "description": "Students compare civilian, judicial, federal, and public accountability mechanisms."}, {"id": "45ad96d1-bdb9-454e-a615-5515872bf890", "type": "subtopic", "title": "Misconduct and remedies", "children": [{"id": "c30e32a1-f3ec-4a94-acb6-e961ad6d35b6", "type": "concept", "title": "Excessive force"}, {"id": "626bc3e0-0d8a-4912-9b08-10f169d91748", "type": "concept", "title": "False arrest"}, {"id": "c1b6b2a8-374d-4f1e-9cd8-74e1c3213b60", "type": "concept", "title": "Unlawful search"}, {"id": "781026e4-2a36-4123-a3be-726124d0f5f1", "type": "concept", "title": "Perjury"}, {"id": "3a8052ed-42de-46e4-a7d9-aad512e2e56e", "type": "concept", "title": "Brady/Giglio issues"}, {"id": "d6b813d5-8229-4453-a5eb-78fdd05c0a4d", "type": "concept", "title": "Qualified immunity"}, {"id": "6b842754-f0d0-4ca2-8361-3fbd6ef0e149", "type": "concept", "title": "Section 1983"}, {"id": "eb27aba9-d340-48a3-bbdb-a5d59555c274", "type": "concept", "title": "Criminal prosecution"}], "description": "The point is to understand misconduct categories and the legal/policy tools used to address them."}]}, {"id": "a65d9f93-8181-4a32-8f85-daba360a7f70", "type": "topic", "title": "Policing Data, Crime Measurement, and Evidence-Based Practice", "description": "Police policy should be evaluated with data, but data also reflect reporting choices and institutional incentives. Students learn to read official data critically and use evidence responsibly.", "children": [{"id": "abe86260-bc3c-4dfe-8655-816d7c4ef020", "type": "subtopic", "title": "Crime and police data systems", "children": [{"id": "80057e27-3301-494d-843b-00f7d10de348", "type": "concept", "title": "UCR"}, {"id": "66b68d0c-c632-4455-9600-f3e3c285f19a", "type": "concept", "title": "NIBRS"}, {"id": "d9274743-173a-474f-923a-ebba11c761b4", "type": "concept", "title": "FBI Crime Data Explorer"}, {"id": "d7afb566-d646-41f1-8da8-359ffc7ca709", "type": "concept", "title": "BJS LEMAS"}, {"id": "ccd44a81-f1db-4bb5-918a-3bd3a92289bf", "type": "concept", "title": "CLETA"}, {"id": "1c88872a-1b99-48c4-a2d4-42b58b81487b", "type": "concept", "title": "LEARCAT"}, {"id": "f2a5adfe-dba4-4d32-a390-3125b94fbc0e", "type": "concept", "title": "Calls for service"}, {"id": "acfb906b-3791-4444-84ea-d9d76fbfd287", "type": "concept", "title": "Arrest data"}, {"id": "091c69dd-9b8d-4a1c-b65f-0f6c58830e8b", "type": "concept", "title": "Use-of-force data"}], "description": "Students learn major data sources and their limitations."}, {"id": "6d5e0ca0-c71b-4c3d-8ee3-da526d93ae53", "type": "subtopic", "title": "Evidence-based policing", "children": [{"id": "8af7d0b5-120c-4dd4-b100-f5c9fc66829e", "type": "concept", "title": "Randomized controlled trials"}, {"id": "414000b1-93dd-4b48-98eb-8ef055cd2265", "type": "concept", "title": "Quasi-experiments"}, {"id": "0085995c-62f4-4ce5-9757-0db6d2bc23e9", "type": "concept", "title": "Systematic reviews"}, {"id": "1f97e3ff-0a62-474b-9340-bc822b339809", "type": "concept", "title": "Hot spots evidence"}, {"id": "9b990c9a-692e-44ae-a543-294dcac0b754", "type": "concept", "title": "Focused deterrence"}, {"id": "1a454712-edfa-497a-806f-07a3792f7c9e", "type": "concept", "title": "Procedural justice research"}, {"id": "06aa9374-e2ea-4d9d-9061-7006bd8fcda0", "type": "concept", "title": "Implementation fidelity"}, {"id": "a65dd3d3-a825-4e58-abbf-605c574561b8", "type": "concept", "title": "Outcome measures"}], "description": "Students learn how research can guide patrol, investigation, and prevention strategies."}, {"id": "a30aa351-d682-4218-b03d-c4c4eeabf1eb", "type": "subtopic", "title": "Data ethics and interpretation", "children": [{"id": "590a1f04-74a5-411b-989a-2a06263a71d3", "type": "concept", "title": "Underreporting"}, {"id": "10906f29-6688-42f2-9e67-4606a5eec394", "type": "concept", "title": "Clearance rates"}, {"id": "7fe8cf7b-77f7-4bd5-993d-df76b09c44c5", "type": "concept", "title": "Dark figure of crime"}, {"id": "8abee299-3423-43f5-b3d6-22161272728c", "type": "concept", "title": "Benchmarking"}, {"id": "a88968b6-10ad-49ef-a23f-2d4b767532eb", "type": "concept", "title": "Selection bias"}, {"id": "08f04ff4-c75b-456e-9ef8-7e01c093a2b7", "type": "concept", "title": "Data quality"}, {"id": "69b9acc8-8c46-4f8e-baf8-e3eaa27e5b7d", "type": "concept", "title": "Public dashboards"}, {"id": "d53a231d-370a-4993-a873-4f38c08259ef", "type": "concept", "title": "Privacy"}], "description": "The goal is to avoid naive data use and spot incentives that distort measurement."}]}, {"id": "9d56ebd4-41f6-4c20-8d85-a33a22b902d6", "type": "topic", "title": "Technology, Surveillance, Body Cameras, and Digital Evidence", "description": "Technology changes what police can see, store, predict, and prove. This unit evaluates tools through effectiveness, legality, civil liberties, bias, security, and community consent.", "children": [{"id": "e4981795-e508-4cf7-9677-3b907e4470f2", "type": "subtopic", "title": "Operational technologies", "children": [{"id": "07c61602-e246-4e3b-9874-52ce1bdf47ed", "type": "concept", "title": "Body-worn cameras"}, {"id": "667ad658-2247-4e0b-af1d-acf020307cc4", "type": "concept", "title": "Dash cameras"}, {"id": "8d455d3a-de8f-48fa-ab99-1c33d2b187f9", "type": "concept", "title": "License plate readers"}, {"id": "2519072b-2af4-4848-bd85-c2a9bf4f0fe6", "type": "concept", "title": "Shot detection"}, {"id": "99fe409d-1ce9-4b46-9e94-fd2f7fc0ff2b", "type": "concept", "title": "Drones"}, {"id": "ae8d229a-29f5-45fd-9298-68fbcfe1cb29", "type": "concept", "title": "CAD/RMS"}, {"id": "e225a83b-12a9-4093-a1ab-802649fe7cbc", "type": "concept", "title": "Mobile data terminals"}, {"id": "7e8958ab-90e0-4644-8134-40071e90833d", "type": "concept", "title": "Digital evidence systems"}], "description": "Students learn common police technologies and what problems they claim to solve."}, {"id": "c5a4898a-538b-4bfb-85fd-c80fa64332c6", "type": "subtopic", "title": "Surveillance and analytics", "children": [{"id": "8ce5fd56-4ca9-4194-a641-b5ba22608d7e", "type": "concept", "title": "Facial recognition"}, {"id": "b67446d7-5c0e-4e99-80e5-937c383c200a", "type": "concept", "title": "Predictive policing"}, {"id": "169cbc0d-dce1-4bef-abc3-b2cadd2eb53e", "type": "concept", "title": "Social media monitoring"}, {"id": "995002e0-4219-4226-afbc-4aedcc8c01f2", "type": "concept", "title": "Real-time crime centers"}, {"id": "b86d4bfa-12aa-4768-8692-25d8d96b93f3", "type": "concept", "title": "Network analysis"}, {"id": "4579a26e-e230-49d3-a27c-845b09044f36", "type": "concept", "title": "Geofencing warrants"}, {"id": "514c446a-b835-488e-920b-d3e4d478b0eb", "type": "concept", "title": "Data fusion"}, {"id": "b2a95750-3416-41fe-80d0-5dc49b4f5e7f", "type": "concept", "title": "Algorithmic bias"}], "description": "Students evaluate surveillance and algorithmic tools that can expand police capacity and risk."}, {"id": "67402bbc-6f47-41c6-9ddd-f817bbe61d43", "type": "subtopic", "title": "Policy controls", "children": [{"id": "fc94822e-21eb-44fa-8b4e-f41ba9c171c8", "type": "concept", "title": "Use policy"}, {"id": "5e72040e-722d-47da-a4d9-dd69677fd2f1", "type": "concept", "title": "Retention rules"}, {"id": "13b01e2b-cfc6-4821-ac71-3b3138d9b253", "type": "concept", "title": "Audit logs"}, {"id": "b5183fb6-7329-4816-a4c2-39375dd560d8", "type": "concept", "title": "Access control"}, {"id": "17d0b033-c74f-441a-acc7-560b25be63bb", "type": "concept", "title": "Public notice"}, {"id": "2266cfd1-3121-4c29-9593-3942ef797982", "type": "concept", "title": "Impact assessments"}, {"id": "b27258b4-e03d-4a2d-be82-62f2a9d16540", "type": "concept", "title": "Vendor contracts"}, {"id": "3880cdf0-cd87-4c73-9042-e29ab9b82b33", "type": "concept", "title": "Cybersecurity"}], "description": "The point is to design governance before technology becomes routine."}]}, {"id": "143b1e1d-7f9c-46ef-b95e-a09feef2539d", "type": "topic", "title": "Specialized Policing Contexts and Vulnerable Populations", "description": "Police often encounter crises and vulnerabilities that require specialized responses beyond standard enforcement. Students learn how agencies handle mental health, domestic violence, youth, homelessness, immigration, and mass events.", "children": [{"id": "d7d6b23a-31c1-496c-9220-bbfe1f426943", "type": "subtopic", "title": "Crisis and behavioral health response", "children": [{"id": "74f42eaf-9b63-4bdd-9be7-609111875683", "type": "concept", "title": "Crisis intervention teams"}, {"id": "d12bfe37-6445-42b3-be70-5282bd4bca12", "type": "concept", "title": "Co-responder models"}, {"id": "084af57d-af96-4745-a8d6-7ba77fd9e322", "type": "concept", "title": "Mobile crisis teams"}, {"id": "a480f5e3-d1cc-4f13-becc-d02670daa4bc", "type": "concept", "title": "988 coordination"}, {"id": "0703dc04-3675-470c-9e02-a03992d5ba3e", "type": "concept", "title": "Excited delirium controversies"}, {"id": "a472b63d-a143-470a-ba9f-e352d208216b", "type": "concept", "title": "Suicide calls"}, {"id": "49a29dfd-9f67-4cdc-be3a-155375a7ede5", "type": "concept", "title": "Welfare checks"}, {"id": "6782f1e5-9778-4af0-9a24-b3138153677a", "type": "concept", "title": "Diversion"}], "description": "Students examine when police should respond, when alternatives are better, and how co-response models work."}, {"id": "b5ffe2da-1602-4978-bf80-69365e564a87", "type": "subtopic", "title": "Victim-centered and youth encounters", "children": [{"id": "3069258a-bed6-4bf3-9634-d05ffac84347", "type": "concept", "title": "Domestic violence"}, {"id": "3c80f06c-6216-4e54-82cc-50eddbf13c2d", "type": "concept", "title": "Sexual assault response"}, {"id": "28b1fe0f-ec0e-4359-8323-acc3dc4e98a1", "type": "concept", "title": "Human trafficking"}, {"id": "1d7281b4-6c91-46e2-bdca-34ad5f69aa43", "type": "concept", "title": "Child abuse"}, {"id": "209cb7d4-b850-414a-9b71-619583fd7f96", "type": "concept", "title": "Police-juvenile encounters"}, {"id": "48604af8-d04a-4344-a790-291e7146757e", "type": "concept", "title": "School resource officers"}, {"id": "cef57a2b-f3ce-47ae-bcaa-738004567d42", "type": "concept", "title": "Mandatory arrest"}, {"id": "f0aa64b9-f5a6-4bd9-b05f-61361a7b024a", "type": "concept", "title": "Victim services"}], "description": "Students learn how trauma, age, family dynamics, and victim safety shape police response."}, {"id": "707e0448-1ab5-4050-9784-a5a96af41c06", "type": "subtopic", "title": "Public order and special events", "children": [{"id": "f57b92ff-7c23-4832-89ea-f1a52764d90f", "type": "concept", "title": "Crowd control"}, {"id": "af8b76ed-4278-43b8-884c-00c2f2030121", "type": "concept", "title": "First Amendment activity"}, {"id": "899fc2cf-8478-4930-8b6e-2d3c3491f449", "type": "concept", "title": "Civil disorder units"}, {"id": "51f5cab7-97ed-42e9-8c3d-cc05bf89803f", "type": "concept", "title": "Mutual aid"}, {"id": "2882ca02-374a-42c6-a5ab-e25fd86f3c3b", "type": "concept", "title": "Incident command"}, {"id": "557ee97c-9996-4a82-aaab-c79f55d3d695", "type": "concept", "title": "Mass casualty response"}, {"id": "5ce4bf3e-08df-480e-81bc-653b39eadbc8", "type": "concept", "title": "Disaster policing"}, {"id": "f9ebac6a-ebd6-45ca-bf31-93750cf5253d", "type": "concept", "title": "After-action reporting"}], "description": "The goal is to understand crowd management, protest policing, and emergency coordination."}]}, {"id": "2d710e32-fc32-432e-a025-31a4155aa152", "type": "topic", "title": "Officer Wellness, Ethics, and Professional Identity", "description": "Healthy, ethical organizations are safer for officers and the public. This unit connects wellness, trauma, supervision, integrity, peer intervention, and professional identity.", "children": [{"id": "c97a2ba9-2916-47f8-a60a-ecc11391a0aa", "type": "subtopic", "title": "Officer wellness", "children": [{"id": "a4a89646-c2a2-437f-a86b-ca9355624a3d", "type": "concept", "title": "Shift work"}, {"id": "70666a2b-049e-46eb-883c-a585b0abe70b", "type": "concept", "title": "Sleep deprivation"}, {"id": "3ab10a54-2587-4ddb-9a70-a45079036c3d", "type": "concept", "title": "Hypervigilance"}, {"id": "e8677963-a3c2-4408-9ed4-506da149c501", "type": "concept", "title": "Trauma exposure"}, {"id": "64e49f4e-5e3a-4507-8b22-19b0f1207060", "type": "concept", "title": "Suicide risk"}, {"id": "d32e572a-75c6-4db9-8ae1-5acd4f70f0ff", "type": "concept", "title": "Peer support"}, {"id": "5328025b-5895-478a-9d3f-4681e5b09c0e", "type": "concept", "title": "Employee assistance programs"}, {"id": "c996f8e3-3335-4110-bdc3-72b87389816c", "type": "concept", "title": "Family stress"}], "description": "Students learn how stress and trauma affect behavior, retention, and decision-making."}, {"id": "953b1039-e236-4ae4-8d50-0a39cdc1a75d", "type": "subtopic", "title": "Police ethics", "children": [{"id": "b3d494c3-1f65-4cac-88e1-3003a1564644", "type": "concept", "title": "Noble cause corruption"}, {"id": "5501723e-a18a-47e3-9ed9-b9ee7060167a", "type": "concept", "title": "Gratuities"}, {"id": "ff33ca1b-a919-48b5-8d89-514cc624ad9a", "type": "concept", "title": "Conflicts of interest"}, {"id": "93bc471b-94e3-42cf-953c-c1e83ea9a818", "type": "concept", "title": "Bias"}, {"id": "a14306a2-a25c-4952-8dc5-ad7d328d89da", "type": "concept", "title": "Truthfulness"}, {"id": "8ea2ebe1-657d-472a-951c-bbfae249121c", "type": "concept", "title": "Brady/Giglio disclosure"}, {"id": "7e51ba6c-9d41-499a-846c-ee0b45a8f9c1", "type": "concept", "title": "Duty to report"}, {"id": "748e24f4-ff7a-44cc-824e-e4855122cbcb", "type": "concept", "title": "Duty to intervene"}], "description": "Students examine integrity problems that arise from discretion, loyalty, and authority."}, {"id": "6c6722f1-6813-4df3-9df9-2bf045bf397c", "type": "subtopic", "title": "Leadership and culture change", "children": [{"id": "f521a7bb-2ef5-4e4f-87d7-4c79d007e685", "type": "concept", "title": "First-line supervision"}, {"id": "392a0963-16b9-4712-a27c-1b2bc87e1790", "type": "concept", "title": "Roll-call training"}, {"id": "ee08addf-ec22-4fe4-abb8-11cc6bbc6aa3", "type": "concept", "title": "Mentorship"}, {"id": "561a3a66-5fde-4b3a-a81f-92d5b93b927d", "type": "concept", "title": "Peer intervention"}, {"id": "bb1b7cf2-a41c-4eca-ae92-b193d4826478", "type": "concept", "title": "Accountability culture"}, {"id": "194c865e-8c14-4831-98e8-8b267b9104d2", "type": "concept", "title": "Learning organization"}, {"id": "da631f2f-4d19-4689-980a-19154fe6eb87", "type": "concept", "title": "CompStat pressure"}, {"id": "e9706147-2b71-4e69-854b-6d06b15aef5e", "type": "concept", "title": "Organizational justice"}], "description": "The point is to understand how supervisors and executives shape norms."}]}, {"id": "38594b0f-5605-4ba3-b8d5-87d2c00e32fd", "type": "topic", "title": "Homeland Security, Federalism, and Interagency Policing", "description": "Modern policing operates across local, state, federal, and private boundaries. Students learn how homeland security, intelligence, task forces, and interagency partnerships affect l